//! From `tungsten-mc-compile/src/transform_spmt/noise.rs` (`lower_normal_noise`): statements
//! generated by loops over octaves, two permutation tables per octave, method-style bodies, and
//! the `as_density` choice between a unit and a helper. Twin: `builder/noise.tw`.
//!
//! The toy runtime has no Perlin noise, so each octave samples the position linearly and adds
//! `perm_get(t, 7) - perm_get(t, 263)`, which is 0 for every table but still reads it. The
//! octave list, the second sampler's frequency factor and the amplitude are exact binary
//! numbers instead of vanilla's, so the expected values can be computed by hand.

use tungsten_builder::prelude::*;

extern_fns! {
    group noise_externs;
    perm_get(t: (handle "PerlinNoiseSampler"), i: I32): I32,
}

/// Stands in for vanilla's `DOUBLE_PERLIN_OFFSET`.
const SECOND_SAMPLER_FACTOR: f64 = 2.0;

struct NormalNoise {
    /// (frequency, amplitude, octave id), already filtered and weighted.
    octaves: Vec<(f64, f64, i32)>,
    amplitude: f64,
}

enum Lowered {
    Density(Unit),
    Function(Helper),
}

/// What a frontend's string-to-seed derivation gives (the builder knows no hashing). Here the
/// three names the slice uses, as vanilla's MD5 split.
fn name_seed(name: &str) -> (i64, i64) {
    match name {
        "n" => (8902374405288272100, 1924477296749798305),
        "octave_-1" => (-2882966581331622803, -8741388887387168150),
        "octave_1" => (7612244814648660239, 6262469271084829834),
        other => panic!("no seed for `{other}`"),
    }
}

fn lower_normal_noise(
    pb: &mut ProgramBuilder,
    noise: &NormalNoise,
    permutation_name: &str,
    name: &str,
    as_density: bool,
) -> Lowered {
    let seed = pb.param("seed", I64);
    let mut f = FnBuilder::new(name, F64);
    let rpos3 = if as_density {
        let rpos3 = f.local("rpos3", Vec3);
        f.assign(rpos3, origin() + pos3());
        rpos3
    } else {
        f.param("rpos3", Vec3)
    };

    let n = f.local("n", F64);
    f.assign(n, 0.0);
    for &(freq, amp, octave) in &noise.octaves {
        let sub = format!("octave_{octave}");
        let (id, sub_id) = (name_seed(permutation_name), name_seed(&sub));
        let tables = [0i64, 1].map(|index| {
            pb.auto_const(
                &format!("{permutation_name}_{index}_{sub}"),
                Handle("PerlinNoiseSampler"),
                "make_permutation_table",
                [seed.into(), id.0.into(), id.1.into(), index.into(), sub_id.0.into(), sub_id.1.into()],
            )
        });
        for (table, factor) in tables.into_iter().zip([1.0, SECOND_SAMPLER_FACTOR]) {
            let fr = freq * factor;
            // No scalar broadcast: the frontend's `rpos3 * freq` becomes a vec3 product.
            let sample = (rpos3 * vec3!(fr, fr, fr)).x();
            let zero = (perm_get(table, 7) - perm_get(table, 263)).cast(F64);
            f.assign(n, n + sample * amp + zero);
        }
    }
    f.ret(n * noise.amplitude);

    if as_density {
        Lowered::Density(pb.finish_unit(f))
    } else {
        Lowered::Function(pb.finish_helper(f))
    }
}

fn build() -> Result<OptimizedProgram, BuildErrors> {
    let noise = NormalNoise {
        octaves: vec![(0.5, 0.5, -1), (2.0, 0.25, 1)],
        amplitude: 2.0,
    };
    let grid = Grid::new((4, 1, 1));
    let mut pb = ProgramBuilder::new();

    let Lowered::Density(density) = lower_normal_noise(&mut pb, &noise, "n", "noise_density", true)
    else {
        unreachable!()
    };
    let Lowered::Function(helper) = lower_normal_noise(&mut pb, &noise, "n", "noise_fn", false)
    else {
        unreachable!()
    };

    let mut f = FnBuilder::new("calls_noise", F64);
    let p = pos3().x().cast(F64);
    f.ret(helper.call([vec3!(p, 0.0, 0.0)]));
    let caller = pb.finish_unit(f);

    pb.entry(density, grid);
    pb.entry(caller, grid);
    pb.build()
}

#[test]
fn noise() {
    super::check_slice(build(), "builder/noise");
    assert_eq!(noise_externs().externs.len(), 1);
}
